/**
 * Generates src/data/dictionary.js from the SCOWL-derived `wordlist-english`
 * package (a devDependency).  Run with `npm run build:dict`.
 *
 * The generated file is committed so the game runs from a static file server
 * with no build step.
 */
import { createRequire } from 'node:module';
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');

/** SCOWL size tiers to include.  10/20 are everyday words, 35-50 widen it. */
const TIERS = [10, 20, 35, 40, 50];
/** Tiers considered "everyday English" -- flagged so the game can praise them. */
const COMMON_TIERS = new Set([10, 20]);
const VARIANTS = ['english', 'american'];

const MIN_LEN = 3;
const MAX_LEN = 8;

/**
 * Words that must never score in a game aimed at English learners.  Kept
 * deliberately small: it only has to cover what SCOWL's common tiers contain.
 */
const BLOCKED = new Set([
  'arse', 'arsehole', 'ass', 'asses', 'asshole', 'assholes', 'bastard',
  'bastards', 'bitch', 'bitches', 'bollocks', 'boob', 'boobs', 'bugger',
  'bullshit', 'cock', 'cocks', 'coon', 'coons', 'crap', 'crappy', 'cum',
  'cunt', 'cunts', 'dago', 'dick', 'dicks', 'dildo', 'dyke', 'dykes',
  'fag', 'fags', 'faggot', 'faggots', 'fart', 'farts', 'fuck', 'fucked',
  'fucker', 'fuckers', 'fucking', 'fucks', 'gook', 'gooks', 'jism', 'jizz',
  'kike', 'kikes', 'nigger', 'niggers', 'nigga', 'niggas', 'penis', 'piss',
  'pissed', 'pisses', 'pissing', 'poop', 'porn', 'porno', 'prick', 'pricks',
  'pussies', 'pussy', 'queer', 'queers', 'rape', 'raped', 'rapes', 'raping',
  'rapist', 'rapists', 'retard', 'retards', 'scrotum', 'semen', 'shit',
  'shits', 'shitted', 'shitting', 'shitty', 'slut', 'sluts', 'spic', 'spics',
  'tits', 'titties', 'titty', 'turd', 'turds', 'twat', 'twats', 'wank',
  'wanker', 'wankers', 'whore', 'whores', 'wog', 'wogs', 'wop',
]);

/** tier of each accepted word (lowest tier wins) */
const tierOf = new Map();

for (const tier of TIERS) {
  for (const variant of VARIANTS) {
    let list;
    try {
      list = require(`wordlist-english/${variant}-words-${tier}.json`);
    } catch {
      continue; // variant/tier combination not shipped
    }
    for (const raw of list) {
      const word = String(raw);
      // Proper nouns and initialisms (SCOWL ships a handful, e.g. "OK") are
      // not words a speller should be credited for.
      if (word !== word.toLowerCase()) continue;
      if (word.length < MIN_LEN || word.length > MAX_LEN) continue;
      if (!/^[a-z]+$/.test(word)) continue;
      if (BLOCKED.has(word)) continue;
      if (!tierOf.has(word)) tierOf.set(word, tier);
    }
  }
}

const words = [...tierOf.keys()].sort();
const byLength = new Map();
const commonByLength = new Map();
for (const word of words) {
  if (!byLength.has(word.length)) byLength.set(word.length, []);
  byLength.get(word.length).push(word);
  if (COMMON_TIERS.has(tierOf.get(word))) {
    if (!commonByLength.has(word.length)) commonByLength.set(word.length, []);
    commonByLength.get(word.length).push(word);
  }
}

/** Packs same-length words into chunked string literals for a readable diff. */
function packBlock(list, length, wordsPerLine = 12) {
  const lines = [];
  for (let i = 0; i < list.length; i += wordsPerLine) {
    lines.push(`    '${list.slice(i, i + wordsPerLine).join('')}',`);
  }
  return `  ${length}: [\n${lines.join('\n')}\n  ],`;
}

function renderTable(map, name, doc) {
  const body = [...map.keys()]
    .sort((a, b) => a - b)
    .map((length) => packBlock(map.get(length), length))
    .join('\n');
  return `${doc}\nexport const ${name} = {\n${body}\n};\n`;
}

const header = `// @generated by tools/build-dictionary.mjs -- do not edit by hand.
//
// Word data derived from SCOWL via the \`wordlist-english\` package.
//   Copyright 2000-2016 by Kevin Atkinson.  Permission to use, copy, modify,
//   distribute and sell these word lists, the associated scripts, the output
//   created from the scripts, and its documentation for any purpose is hereby
//   granted without fee, provided that the above copyright notice appears in
//   all copies and that both that copyright notice and this permission notice
//   appear in supporting documentation.  Kevin Atkinson makes no
//   representations about the suitability of this array for any purpose.  It
//   is provided "as is" without express or implied warranty.
//
// ${words.length} words, ${MIN_LEN}-${MAX_LEN} letters.  Each entry below is a
// run of fixed-width words concatenated together: at \`${'${length}'}: [...]\` every
// word is exactly \`length\` characters long, so the block splits unambiguously.
`;

const out = [
  header,
  `export const MIN_WORD_LENGTH = ${MIN_LEN};`,
  `export const MAX_WORD_LENGTH = ${MAX_LEN};`,
  '',
  renderTable(byLength, 'WORD_BLOCKS', '/** Every scoring word, keyed by length. */'),
  renderTable(
    commonByLength,
    'COMMON_WORD_BLOCKS',
    '/** The everyday-English subset (SCOWL tiers 10 and 20), keyed by length. */',
  ),
].join('\n');

mkdirSync(resolve(ROOT, 'src/data'), { recursive: true });
writeFileSync(resolve(ROOT, 'src/data/dictionary.js'), out);

const commonCount = [...commonByLength.values()].reduce((n, l) => n + l.length, 0);
console.log(`wrote src/data/dictionary.js: ${words.length} words (${commonCount} common)`);
for (const length of [...byLength.keys()].sort((a, b) => a - b)) {
  console.log(`  ${length} letters: ${byLength.get(length).length}`);
}
